insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'sla_7_v1'
from (values
('128.21.b.1.A',3,'A sixth grader hears a classmate''s directions and is unsure about step three. What is the best response?','["ask a clarifying question about step three", "walk away from the speaker", "change the topic", "stay quiet and guess"]'::jsonb,0,'Active listeners ask clarifying questions.','original'),
('128.21.b.1.A',3,'Which behavior shows active listening during a group talk?','["doodling with the head down", "paraphrasing the speaker''s point before replying", "finishing the speaker''s sentences", "looking at the clock"]'::jsonb,1,'Paraphrasing shows the message was understood.','original'),
('128.21.b.1.B',3,'Which set of oral directions has multiple action steps?','["Please sit down.", "Hello, class.", "Open the folder, label the page and then hand it in.", "Open the folder."]'::jsonb,2,'Multi-step directions include several actions in order.','original'),
('128.21.b.1.B',3,'When giving oral instructions with several steps, a speaker should:','["speak as fast as possible", "skip the middle steps", "give the steps at random", "use order words such as first, next and last"]'::jsonb,3,'Order words keep steps clear.','original'),
('128.21.b.1.C',3,'A presentation with a stance should begin by:','["stating the position clearly", "reading the bibliography", "apologizing for speaking", "hiding the topic"]'::jsonb,0,'The stance guides the whole talk.','original'),
('128.21.b.1.C',3,'Which delivery choice makes a speech more convincing?','["speaking with no pauses", "steady eye contact and a clear voice", "turning away from listeners", "whispering to the floor"]'::jsonb,1,'Eye contact and voice build credibility.','original'),
('128.21.b.1.D',3,'In a student-led discussion, the leader elicits suggestions by:','["answering every question alone", "ignoring quiet members", "inviting each member to share an idea", "ending the talk early"]'::jsonb,2,'Eliciting means drawing out ideas.','original'),
('128.21.b.1.D',3,'A group member disagrees politely when they:','["interrupt loudly", "leave the group", "roll their eyes", "acknowledge the idea and then offer a different view"]'::jsonb,3,'Respectful disagreement keeps discussion productive.','original'),
('128.21.b.10.A',3,'The author''s purpose of a public-safety brochure about helmets is most likely to:','["persuade readers to wear them", "entertain with a joke", "describe a dream", "retell a legend"]'::jsonb,0,'Safety brochures usually persuade.','original'),
('128.21.b.10.A',3,'A message of a text is the:','["number of pages", "big idea the author wants readers to take away", "print date", "font style"]'::jsonb,1,'The message is the lesson or point of the text.','original'),
('128.21.b.10.B',3,'A text that explains a problem and then gives fixes uses which structure?','["description only", "sequence of recipes", "problem and solution", "chronological order"]'::jsonb,2,'Problem-solution texts state a problem, then answers.','original'),
('128.21.b.10.B',3,'Text structure supports the author''s purpose when:','["the sentences are shuffled", "headings are removed", "the ideas are unrelated", "cause-and-effect order shows why events happened"]'::jsonb,3,'Structure should fit the purpose.','original'),
('128.21.b.10.C',3,'A bolded term and a diagram in a science chapter help the reader by:','["highlighting key vocabulary and showing how parts relate", "hiding the topic", "replacing all words", "making text longer"]'::jsonb,0,'Print and graphic features guide understanding.','original'),
('128.21.b.10.C',3,'Why would an author include a map in a history article?','["to give a recipe", "to show where events took place", "to rhyme with the title", "to list page numbers"]'::jsonb,1,'Maps clarify location.','original'),
('128.21.b.10.D',3,'''Her smile was a sunrise'' is an example of:','["alliteration", "rhyme", "metaphor", "personification"]'::jsonb,2,'It compares without using like or as.','original'),
('128.21.b.10.E',3,'A narrator who knows the thoughts of every character uses:','["second person only", "no point of view", "limited point of view", "omniscient point of view"]'::jsonb,3,'Omniscient narrators know all characters'' thoughts.','original'),
('128.21.b.10.E',3,'In limited point of view, the reader learns the thoughts of:','["one character only", "the author''s friends", "no character", "every character"]'::jsonb,0,'Limited narrators focus on one character.','original'),
('128.21.b.10.F',3,'Words such as shadowy, creaking and eerie help create a:','["math mood", "spooky mood", "cheerful mood", "silly mood"]'::jsonb,1,'Word choice shapes mood.','original'),
('128.21.b.10.G',4,'Which statement describes a logical fallacy?','["a strong fact", "a verified quote", "faulty reasoning that weakens an argument", "an accurate statistic"]'::jsonb,2,'Fallacies are errors in reasoning.','original'),
('128.21.b.10.G',4,'A rhetorical device differs from a logical fallacy because it:','["is only found in math", "is always false", "is never used by writers", "is a technique used to persuade, not necessarily an error"]'::jsonb,3,'Rhetorical devices are persuasive tools.','original'),
('128.21.b.11.A',3,'A student wants to inform classmates about recycling. A fitting genre is a:','["multi-paragraph informational essay", "limerick", "dialogue script only", "riddle"]'::jsonb,0,'The genre should match purpose and audience.','original'),
('128.21.b.11.A',3,'Planning a first draft often includes:','["printing the cover", "choosing a topic, audience and organization", "deleting all notes", "proofreading final copies"]'::jsonb,1,'Planning comes before drafting.','original'),
('128.21.b.11.B.i',3,'Transitions such as however and in addition help writers to:','["avoid evidence", "shorten sentences", "connect ideas smoothly", "repeat words"]'::jsonb,2,'Transitions create coherence.','original'),
('128.21.b.11.B.i',3,'An introduction in an essay usually:','["lists the sources", "ends the essay", "repeats the title", "presents the topic and controlling idea"]'::jsonb,3,'The introduction sets up the thesis.','original'),
('128.21.b.11.B.ii',3,'Which detail adds depth to a paragraph about volcanoes?','["Mount St. Helens erupted in 1980 and sent ash across several states.", "Some are big.", "Volcanoes are things.", "There are mountains."]'::jsonb,0,'Specific facts add depth.','original'),
('128.21.b.11.B.ii',3,'An engaging idea in writing is best developed with:','["random words", "specific facts and examples", "vague claims", "copied sentences"]'::jsonb,1,'Specificity supports ideas.','original'),
('128.21.b.11.C',3,'During revision, a writer should first look at:','["the page border", "the font color", "clarity, organization and word choice", "only commas"]'::jsonb,2,'Revision improves ideas, not just mechanics.','original'),
('128.21.b.11.C',3,'Varying sentence length during revision helps by:','["hiding the claim", "adding errors", "making all sentences equal", "improving rhythm and keeping readers interested"]'::jsonb,3,'Sentence variety improves style.','original'),
('128.21.b.11.D.i',3,'Which fix repairs the run-on ''The bell rang we left''?','["The bell rang, and we left.", "The bell rang, we left.", "The bell, rang we left.", "The bell rang we left."]'::jsonb,0,'A comma plus a conjunction joins independent clauses.','original'),
('128.21.b.11.D.ii',3,'Which sentence keeps a consistent verb tense?','["Marco open the door and walking inside.", "Marco opened the door and walked inside.", "Marco opened the door and walks inside.", "Marco opens the door and walked inside."]'::jsonb,1,'Both verbs are in the past.','original'),
('128.21.b.11.D.iv',4,'Choose the correct verb: ''The box of pencils ___ on the desk.''','["sitting", "are sitting", "sits", "sit"]'::jsonb,2,'The subject is box, not pencils.','original'),
('128.21.b.11.D.iv',4,'In ''A group of birds flies overhead,'' the verb agrees with:','["the adverb", "the plural noun inside the phrase", "the verb itself", "the singular noun that begins the sentence"]'::jsonb,3,'The prepositional phrase does not change agreement.','original'),
('128.21.b.11.D.v',3,'Which pronoun is indefinite?','["everyone", "himself", "they", "their"]'::jsonb,0,'Indefinite pronouns do not name a specific person.','original'),
('128.21.b.11.D.vi',3,'What position signals the dependent clause in ''Although it rained, we played''?','["the last word", "the first word", "the verb played", "the pronoun we"]'::jsonb,1,'The subordinating conjunction opens the clause.','original'),
('128.21.b.11.D.vii',3,'Which acronym for the National Aeronautics and Space Administration is written correctly?','["NASSA", "NAZA", "NASA", "NASAA"]'::jsonb,2,'Acronyms use capital letters for each initial.','original'),
('128.21.b.11.D.vii',3,'Which of these is a proper noun?','["city", "river", "school", "Austin"]'::jsonb,3,'Names of specific places are capitalized.','original'),
('128.21.b.11.D.viii',3,'Which sentence has a comma after an introductory element?','["After lunch, we hiked up the trail.", "After, lunch we hiked up the trail.", "After lunch we, hiked up the trail.", "After lunch we hiked, up the trail."]'::jsonb,0,'A comma follows the introductory phrase.','original'),
('128.21.b.11.D.viii',3,'Which sentence punctuates a complex sentence correctly?','["When the storm ended the team went, outside.", "When the storm ended, the team went outside.", "When the storm ended the team, went outside.", "When, the storm ended the team went outside."]'::jsonb,1,'Place a comma after an introductory dependent clause.','original'),
('128.21.b.11.D.ix',3,'Which choice uses the correct homophone? ''We left ___ coats at school.''','["ore", "are", "our", "hour"]'::jsonb,2,'Our shows possession.','original'),
('128.21.b.11.D.ix',3,'Which spelling is correct?','["nessecary", "necesary", "neccessary", "necessary"]'::jsonb,3,'Necessary has one c and two s.','original'),
('128.21.b.11.E',2,'Publishing a written piece means:','["sharing the final copy with an audience", "throwing away the draft", "guessing at topics", "outlining only"]'::jsonb,0,'Publishing is the final sharing step.','original'),
('128.21.b.11.E',2,'Which is a way to publish a class report?','["skip the title", "post it on the school website", "leave it in a drawer", "erase it"]'::jsonb,1,'Publishing reaches an audience.','original'),
('128.21.b.12.A',3,'A personal narrative is told from the point of view of:','["a stranger", "a news anchor", "the writer who lived the event", "a robot"]'::jsonb,2,'Personal narratives are first person.','original'),
('128.21.b.12.A',3,'A poem in free verse typically has:','["a table of contents", "strict rhyme", "a bibliography", "no fixed rhyme or meter"]'::jsonb,3,'Free verse breaks traditional patterns.','original'),
('128.21.b.12.B',3,'A multi-paragraph informational essay should include:','["an introduction, body paragraphs and a conclusion", "only one sentence", "stage directions", "rhymes"]'::jsonb,0,'This structure organizes information.','original'),
('128.21.b.12.B',3,'Body paragraphs in an informational essay should:','["tell jokes only", "each develop one supporting idea", "avoid facts", "repeat the title"]'::jsonb,1,'Each paragraph has a focus.','original'),
('128.21.b.12.C',3,'A multi-paragraph argumentative text should contain:','["no position", "only descriptions", "a claim, reasons and evidence", "only a list of dates"]'::jsonb,2,'Arguments need claims and support.','original'),
('128.21.b.12.C',3,'Which sentence best ends an argumentative text?','["That is all I know.", "Recycling exists.", "The end of the page.", "For these reasons, our school should adopt the recycling plan."]'::jsonb,3,'The conclusion restates the claim.','original'),
('128.21.b.12.D',3,'A letter that registers a complaint should:','["state the problem and suggest a fair solution", "avoid a greeting", "insult the reader", "omit details"]'::jsonb,0,'Complaint letters are specific and polite.','original'),
('128.21.b.12.D',3,'Which opening fits a letter requesting information?','["I do not care.", "I am writing to ask about your summer science program.", "You never answer.", "Hey, whatever."]'::jsonb,1,'Request letters state their purpose.','original'),
('128.21.b.13.A',3,'Which question would work best for formal inquiry?','["What is lunch?", "Do you like fish?", "How does water pollution affect local fish populations?", "Is water wet?"]'::jsonb,2,'Researchable questions are specific and open.','original'),
('128.21.b.13.A',3,'A teacher-guided question differs from a student-selected question because it:','["has no answer", "comes from the textbook index only", "is always yes or no", "is suggested by the teacher"]'::jsonb,3,'The teacher offers the question.','original'),
('128.21.b.13.B',3,'Revising a research plan is wise when:','["sources are hard to find or the topic is too broad", "no one asked questions", "the topic is perfect", "the deadline is next year"]'::jsonb,0,'Plans should change with new information.','original'),
('128.21.b.13.B',3,'A plan for a research project should list:','["favorite colors", "questions, sources and deadlines", "lunch menus", "jokes"]'::jsonb,1,'A plan keeps research organized.','original'),
('128.21.b.13.C',3,'A secondary set of questions helps a researcher:','["avoid sources", "write the conclusion first", "narrow or adjust the major research question", "skip notes"]'::jsonb,2,'Smaller questions refine the main one.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Spanish Language Arts and English as a Second Language' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'sla_7_v1'
from (values
('128.21.b.13.C',3,'A major research question that is too broad should be:','["deleted", "copied", "widened further", "narrowed to a focused topic"]'::jsonb,3,'Narrowing makes research manageable.','original'),
('128.21.b.13.D',3,'To gather relevant information efficiently, use:','["headings, keywords and an index", "only the last page", "random pages", "a cover image"]'::jsonb,0,'These tools lead to relevant content.','original'),
('128.21.b.13.D',3,'A variety of sources for a report includes:','["a game rule sheet", "a book, an interview and a reliable website", "three identical pages", "one picture"]'::jsonb,1,'Different sources give a fuller view.','original'),
('128.21.b.13.E',3,'A secondary source:','["is a photograph taken at the time", "is a firsthand speech", "analyzes or reports on events after they happened", "is an original diary"]'::jsonb,2,'Secondary sources interpret primary ones.','original'),
('128.21.b.13.F',3,'Synthesizing sources means:','["copying one source", "listing titles", "skipping evidence", "combining ideas from several sources into new understanding"]'::jsonb,3,'Synthesis merges information.','original'),
('128.21.b.13.F',3,'Which shows synthesis?','["Both the interview and the article show that volunteers boost local parks.", "The interview happened.", "The article is long.", "I liked the title."]'::jsonb,0,'The sentence merges two sources into one claim.','original'),
('128.21.b.13.G',3,'A good paraphrase:','["copies word for word", "restates an idea in your own words and credits the source", "hides the source", "changes only one word"]'::jsonb,1,'Paraphrasing keeps meaning and gives credit.','original'),
('128.21.b.13.H.i',3,'A source is more credible when its author:','["gives only opinions", "sells a product", "is an expert who cites evidence", "is anonymous"]'::jsonb,2,'Expertise and evidence build credibility.','original'),
('128.21.b.13.H.i',3,'Bias in a source means the writer:','["uses only data", "is neutral", "cites experts", "favors one side in an unfair way"]'::jsonb,3,'Bias is one-sided favoritism.','original'),
('128.21.b.13.H.ii',3,'''Everybody knows this movie is the worst ever'' is an example of:','["hyperbole", "a citation", "a timeline", "a fact"]'::jsonb,0,'It exaggerates without evidence.','original'),
('128.21.b.13.I',3,'Academic citations let readers:','["erase evidence", "locate the original sources", "skip reading", "count words"]'::jsonb,1,'Citations credit and point to sources.','original'),
('128.21.b.13.I',3,'Using source material ethically includes:','["inventing quotes", "hiding sources", "quoting accurately and crediting authors", "copying silently"]'::jsonb,2,'Ethical research gives credit.','original'),
('128.21.b.13.J',3,'A student presents research as a short video with narration. This delivery is:','["unrelated to research", "only written", "only silent", "multimodal"]'::jsonb,3,'Video blends audio, visuals and text.','original'),
('128.21.b.13.J',3,'The best mode of delivery depends on the:','["audience and purpose", "font choice", "pencil color", "page margin"]'::jsonb,0,'Mode should fit audience and purpose.','original'),
('128.21.b.2.A.i',3,'Which sentence uses porque correctly?','["No sé el por que.", "No fui porque estaba enfermo.", "Dime el porque de todo.", "¿Porque no fuiste a clase?"]'::jsonb,1,'Porque gives a reason in a statement.','original'),
('128.21.b.2.A.i',3,'Which sentence uses por qué correctly?','["Llegué tarde por qué dormí mal.", "Dime el motivo, porqué lo hiciste.", "¿Por qué llegaste tarde?", "Siempre llego tarde por qué si."]'::jsonb,2,'Por qué (two words, accent) begins a direct question.','original'),
('128.21.b.2.A.ii',3,'The word teléfono is stressed on which syllable?','["the last", "the first only", "the second from the end", "the third from the end"]'::jsonb,3,'It is an esdrújula, stressed on the antepenultimate syllable.','original'),
('128.21.b.2.A.ii',3,'Which word is a palabra grave?','["mesa", "canción", "dígamelo", "teléfono"]'::jsonb,0,'Mesa is stressed on the next-to-last syllable.','original'),
('128.21.b.2.A.iii',3,'The word día contains a:','["prefix", "hiatus", "diphthong", "triphthong"]'::jsonb,1,'The accent breaks the vowel pair into two syllables.','original'),
('128.21.b.2.A.iii',3,'The word cielo contains a:','["suffix", "prefix", "diphthong", "hiatus"]'::jsonb,2,'Ie forms one syllable.','original'),
('128.21.b.2.A.iv',3,'How many syllables are in the word chocolate?','["5", "3", "2", "4"]'::jsonb,3,'The word divides as cho-co-la-te.','original'),
('128.21.b.2.A.iv',3,'The prefix des- in the word deshacer means:','["to undo or reverse", "to add", "to compare", "to repeat"]'::jsonb,0,'Des- reverses the action.','original'),
('128.21.b.2.B.i',3,'Which word must carry a written accent?','["cancion", "canción", "cancione", "cancións"]'::jsonb,1,'Aguda words ending in n carry an accent.','original'),
('128.21.b.2.B.i',3,'Which spelling is correct for a word stressed on the antepenultimate syllable?','["pajaro", "pajáro", "pájaro", "pájáro"]'::jsonb,2,'Esdrújulas always carry an accent.','original'),
('128.21.b.2.B.ii',3,'Which verb form is spelled correctly in the simple past?','["hablo", "háblo", "hablò", "habló"]'::jsonb,3,'The él form of the simple past carries an accent.','original'),
('128.21.b.2.B.ii',3,'Which imperfect form is spelled correctly?','["comíamos", "cómiamos", "comiamos", "comiámos"]'::jsonb,0,'The accent marks the hiatus in comíamos.','original'),
('128.21.b.2.B.iii',3,'Which spelling shows a hiatus correctly?','["páis", "país", "pais", "paíz"]'::jsonb,1,'The accented í keeps the vowels apart.','original'),
('128.21.b.2.B.iii',3,'Which spelling shows a diphthong correctly?','["rüido", "ruído", "ruido", "rúido"]'::jsonb,2,'Ui forms a diphthong and needs no accent here.','original'),
('128.21.b.2.C',2,'When writing in cursive, a student should keep letters:','["drawn as printed capitals", "slanted in different directions", "tiny and detached", "evenly sloped and connected"]'::jsonb,3,'Consistency makes cursive legible.','original'),
('128.21.b.2.C',2,'The purpose of legible handwriting is to:','["communicate clearly to readers", "write faster than anyone", "hide the message", "avoid using pencils"]'::jsonb,0,'Legibility supports communication.','original'),
('128.21.b.3.A',3,'A dictionary entry can show a word''s:','["only its page number", "pronunciation, syllables and meaning", "the weather", "its author''s address"]'::jsonb,1,'Entries include several features.','original'),
('128.21.b.3.A',3,'A thesaurus helps a writer find:','["rhymes only", "maps", "synonyms for a word", "page numbers"]'::jsonb,2,'A thesaurus lists related words.','original'),
('128.21.b.3.B',3,'In ''The arid desert, dry and without rain, stretched far,'' context suggests arid means:','["very crowded", "very wet", "very cold", "very dry"]'::jsonb,3,'The phrase dry and without rain defines it.','original'),
('128.21.b.3.B',3,'An analogy such as ''hot is to cold as tall is to short'' helps show:','["relationships between word meanings", "spelling patterns", "page counts", "font types"]'::jsonb,0,'Analogies compare relationships.','original'),
('128.21.b.3.C',3,'The root graf-, from Greek, appears in the word biografía and means:','["to run", "to write", "to speak", "to see"]'::jsonb,1,'Graf- relates to writing.','original'),
('128.21.b.3.C',3,'The Latin root port- in the word transportar means:','["to cut", "to build", "to carry", "to fear"]'::jsonb,2,'Port- means carry.','original'),
('128.21.b.3.D',3,'Words that are spelled the same but have different meanings are:','["homophones", "synonyms", "antonyms", "homographs"]'::jsonb,3,'Homographs share spelling.','original'),
('128.21.b.4',2,'Strong readers often become stronger writers because:','["reading and writing skills reinforce each other", "speaking is unrelated", "writing removes reading", "listening harms writing"]'::jsonb,0,'Language skills work together.','original'),
('128.21.b.4',2,'Discussing a book with a partner develops:','["only counting", "listening, speaking and comprehension", "nothing", "only handwriting"]'::jsonb,1,'Talk builds multiple skills.','original'),
('128.21.b.5',2,'A student reads an article, discusses it and writes a response. Which skills are integrated?','["only drawing", "only math", "reading, speaking, listening and writing", "none"]'::jsonb,2,'Several language skills work together.','original'),
('128.21.b.5',2,'Taking notes during a lecture combines:','["only reading", "only counting", "only painting", "listening and writing"]'::jsonb,3,'Notetaking links two skills.','original'),
('128.21.b.6.A',3,'A reader sets a purpose for reading by:','["deciding what to learn or enjoy from the text", "closing the book", "skipping the title", "counting the pages"]'::jsonb,0,'Purpose guides attention.','original'),
('128.21.b.6.A',3,'Reading a manual to fix a bike has the purpose to:','["enjoy a mystery", "get the steps for repairing it", "find a rhyme", "learn a legend"]'::jsonb,1,'The purpose is practical.','original'),
('128.21.b.6.B',3,'Which question could a reader ask during reading?','["Where is the cover?", "Is the font bold?", "What clues suggest the character''s real feelings?", "What color is the page?"]'::jsonb,2,'Questions should deepen understanding.','original'),
('128.21.b.6.B',3,'Asking questions after reading helps a reader:','["forget the text", "skip the ending", "avoid thinking", "reflect on and confirm understanding"]'::jsonb,3,'After-reading questions check comprehension.','original'),
('128.21.b.6.C',3,'A reader looks at a book''s title and cover to:','["make a prediction", "count words", "find rhymes", "correct spelling"]'::jsonb,0,'Text features support predictions.','original'),
('128.21.b.6.C',3,'A prediction should be corrected when:','["the font changes", "new evidence in the text contradicts it", "the page turns", "the book ends"]'::jsonb,1,'Evidence confirms or corrects predictions.','original'),
('128.21.b.6.D',3,'Creating mental images helps readers:','["avoid details", "skip paragraphs", "deepen understanding of descriptions", "ignore setting"]'::jsonb,2,'Visualizing makes text vivid.','original'),
('128.21.b.6.D',3,'Which phrase is best for visualizing a setting?','["something happened", "a place", "it was there", "rain drumming on the rusty tin roof"]'::jsonb,3,'Sensory details support imagery.','original'),
('128.21.b.6.E',3,'Relating a novel''s conflict to a current event is a connection to:','["society", "the index", "the glossary", "the page number"]'::jsonb,0,'Text-to-world connections link to society.','original'),
('128.21.b.6.E',3,'Noticing that two stories share a theme is a connection to:','["the price", "another text", "the cover", "the font"]'::jsonb,1,'Text-to-text connections link stories.','original'),
('128.21.b.6.F',3,'''Dani slammed her locker and stormed down the hall.'' A reader can infer Dani is:','["amused", "sleepy", "angry", "relaxed"]'::jsonb,2,'Her actions suggest anger.','original'),
('128.21.b.6.F',3,'A strong inference is supported by:','["a hunch", "the cover only", "one random word", "text evidence plus background knowledge"]'::jsonb,3,'Evidence supports inferences.','original'),
('128.21.b.6.G',3,'A reader decides which details are key by asking which:','["support the main idea", "appear first", "are the longest", "use big words"]'::jsonb,0,'Key details connect to the main idea.','original'),
('128.21.b.6.G',3,'Which is more likely a key idea in an article about bees?','["the article has headings", "bees pollinate many crops", "bees are striped", "bees have wings"]'::jsonb,1,'Pollination is central to the topic.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Spanish Language Arts and English as a Second Language' and d.language = 'en'
