('128.21.b.9.D.ii',3,'A references page shows:','["the villain", "the setting", "the sources an author used", "the plot summary"]'::jsonb,2,'References credit sources.','original'),
('128.21.b.9.D.iii',3,'An organizational pattern that explains what something is and its types is:','["dialogue", "rhyme scheme", "stage direction", "definition and classification"]'::jsonb,3,'It defines and sorts.','original'),
('128.21.b.9.D.iii',3,'An advantage-and-disadvantage text mainly:','["weighs benefits against drawbacks", "tells a legend", "retells a play", "lists rhymes"]'::jsonb,0,'It compares pros and cons.','original'),
('128.21.b.9.E.i',3,'Identifying the claim in an editorial means finding:','["the image only", "the position the writer argues", "the date", "the page"]'::jsonb,1,'The claim is the main position.','original'),
('128.21.b.9.E.i',3,'Which is a claim?','["Schools open in August.", "Tutors exist.", "Schools should offer free tutoring.", "Some kids study."]'::jsonb,2,'A claim takes a position.','original'),
