('128.21.b.11.D.vi',3,'A subordinating conjunction such as ''unless'' or ''while'' introduces:','["a dependent clause", "a stanza", "a heading", "a title"]'::jsonb,0,'These words start clauses that cannot stand alone.','original'),
('128.21.b.11.D.i',3,'A complete complex sentence must have:','["two titles", "one independent clause and at least one dependent clause", "no verbs", "only fragments"]'::jsonb,1,'That is the definition of a complex sentence.','original'),
